result = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(LOWER(status) == LOWER('success'))) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    num_customers = COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com') & 
            HAS(
                transactions_made.WHERE(
                    CONTAINS(ticker.symbol, 'AMZN') |
                    CONTAINS(ticker.symbol, 'AAPL') |
                    CONTAINS(ticker.symbol, 'GOOGL') |
                    CONTAINS(ticker.symbol, 'META') |
                    CONTAINS(ticker.symbol, 'NFLX')
                )
            ) == 1
        )
    )
)

faang_tickers = ('AMZN', 'AAPL', 'GOOGL', 'META', 'NFLX')
distinct_faang_customers = GRAPH.CALCULATE(
    distinct_customer_count=COUNT(
        Customers.WHERE(
            (ENDSWITH(LOWER(email), '.com')) &
            (HAS(transactions_made.WHERE(ISIN(ticker.symbol, faang_tickers))) == 1)
        )
    )
)

result = Customers.WHERE(
    (join_date >= "2023-01-01") & 
    (LOWER(status) == "active")
).PARTITION(
    name="countries", 
    by=country
).CALCULATE(
    country=country,
    count=COUNT(Customers)
)

tac_by_country = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= "2023-01-01")
).PARTITION(
    name="country_groups", by=country
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

customer_metrics = Broker.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_period=DATETIME('now', 'start of month', '-6 months')
).Customers.WHERE(
    (join_date >= start_of_period) & (join_date < start_of_current_month)
).CALCULATE(
    signup_month=JOIN_STRINGS('-', YEAR(join_date), LPAD(MONTH(join_date), 2, '0'))
).PARTITION(
    name='monthly_groups', by=signup_month
).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
)

acp_by_type = DailyPrices.WHERE(
    DATEDIFF("days", date, DATETIME('now')) <= 6
).CALCULATE(
    type_of_ticker=ticker.ticker_type
).PARTITION(
    name="type_groups", by=(type_of_ticker,)
).CALCULATE(
    ticker_type=type_of_ticker,
    average_closing_price=AVG(DailyPrices.close)
)

activity_ratio_by_country = Customers.WHERE(
    (YEAR(join_date) == 2022) & (HAS(transactions_made) == 1)
).PARTITION(
    name="country_groups", by=country
).CALCULATE(
    country=country,
    active_customers_count=COUNT(Customers.WHERE(LOWER(status) == 'active')),
    total_customers_count=COUNT(Customers)
).CALCULATE(
    country=country,
    AR=IFF(total_customers_count > 0, (active_customers_count / total_customers_count) * 100.0, 0.0)
)

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

top_customer_by_transactions_in_join_month = Customers.CALCULATE(
    customer_id=_id,
    customer_name=name,
    num_transactions=COUNT(
        transactions_made.WHERE(
            (YEAR(date_time) == YEAR(join_date)) & (MONTH(date_time) == MONTH(join_date))
        )
    )
).TOP_K(
    1,
    by=num_transactions.DESC()
).CALCULATE(
    _id=customer_id,
    name=customer_name,
    number_of_transactions=num_transactions
)

result = Customers.WHERE(
    HAS(transactions_made.WHERE(LOWER(transaction_type) == LOWER('buy'))) == 1
).CALCULATE(
    customer_id=_id
)

result = DailyPrices.WHERE(
    date >= "2023-04-01"
).PARTITION(
    name="tickers", 
    by=ticker_id
).CALCULATE(
    ticker_id=ticker_id
)

distinct_ticker_ids = DailyPrices.WHERE(date >= '2023-04-01').PARTITION(name="distinct_tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

result = Tickers.WHERE(
    HASNOT(historical_prices) == 1
).CALCULATE(
    ticker_id=_id,
    symbol=symbol
)

result = Transactions.WHERE(
    DATEDIFF("days", date_time, 'now') <= 30
).CALCULATE(
    country_name=customer.country
).PARTITION(
    name="countries", by=country_name
).CALCULATE(
    country=country_name,
    number_of_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(5, by=total_transaction_amount.DESC())

result = Tickers.WHERE(symbol == 'VTI').CALCULATE(
    lowest_close_price=MIN(
        historical_prices.WHERE(
            DATEDIFF("days", date, DATETIME('now')) <= 7
        ).close
    )
)

result = Broker.CALCULATE(
    num_transactions=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME("now")) <= 70
        ).transactions_made
    )
)

result = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    days_to_first_transaction=DATEDIFF("seconds", join_date, MIN(transactions_made.date_time)) / 86400
)

result = Customers.CALCULATE(
    customer_id=_id,
    customer_name=name,
    num_sell_transactions=COUNT(
        transactions_made.WHERE(
            (DATE(date_time) == "2023-04-01") & 
            (LOWER(transaction_type) == "sell")
        )
    )
).TOP_K(1, by=num_sell_transactions.DESC())

sales_by_model = Dealership.Cars.WHERE(
    LIKE(LOWER(vin_number), '%m5%')
).PARTITION(
    name="car_models", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    number_of_sales=COUNT(Cars.sale_records)
)

result = Cars.WHERE(LOWER(make) == LOWER('Toyota')).sale_records.WHERE(
    DATEDIFF("days", sale_date, DATETIME('now')) <= 30
).CALCULATE(
    number_of_sales=COUNT(Sales),
    total_revenue=SUM(sale_price)
).SINGULAR()

result = Sales.WHERE(
    (YEAR(sale_date) == 2023) & 
    (ISIN(MONTH(sale_date), (1, 2, 3)))
).CALCULATE(
    asp_q1_2023 = AVG(Sales.sale_price)
)

asp_q1_2023 = Dealership.CALCULATE(
    asp=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            Sales.WHERE(HAS(payment) == 1).payment.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ), 
        2
    )
)

highest_priced_car = Sales.WHERE(
    HAS(
        car.inventory_snapshots.WHERE(
            (is_in_inventory == False) & (snapshot_date == sale_date)
        )
    ) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    make=car.make,
    model=car.model,
    sale_price=sale_price
)

total_sales_count = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') <= 6))
)

result = Customers.WHERE(
    HAS(car_purchases) == 1
).CALCULATE(
    customer_id=_id
)

distinct_customer_ids = Sales.PARTITION(name="customer_groups", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

result = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == LOWER("cash"))) == 1
).CALCULATE(
    salesperson_id=_id
)

distinct_salesperson_ids = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == 'cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

result = Dealership.CALCULATE(
    num_weekend_payments_to_utility = COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == LOWER('Utility Company')) & 
            ISIN(DAYOFWEEK(payment_date), (1, 7))
        )
    )
)

weekend_payments_to_utility_company = Dealership.CALCULATE(
    num_payments=COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == 'utility company') & 
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

cars_in_inventory = Dealership.CALCULATE(
    latest_snapshot_date=MAX(
        InventorySnapshots.WHERE(
            (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3)
        ).snapshot_date
    )
).InventorySnapshots.WHERE(
    (snapshot_date == latest_snapshot_date) & (is_in_inventory == True)
).car.CALCULATE(
    _id,
    make,
    model,
    year
)

result = Drugs.CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt)
        ).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

avg_ddd_per_drug = Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            (PRESENT(end_dt) == 1) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            ddd_value=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_value
    )
)

