)

overall_d7d100pir = DermTreatment.CALCULATE(
    avg_pasi_d7=AVG(Outcomes.WHERE(PRESENT(day7_pasi_score) & PRESENT(day100_pasi_score)).day7_pasi_score),
    avg_pasi_d100=AVG(Outcomes.WHERE(PRESENT(day7_pasi_score) & PRESENT(day100_pasi_score)).day100_pasi_score)
).CALCULATE(
    d7d100pir=(avg_pasi_d100 - avg_pasi_d7) / avg_pasi_d7 * 100.0
)

result = DermTreatment.CALCULATE(
    pic_female = COUNT(Patients.WHERE(
        (LOWER(gender) == 'female') & 
        (LOWER(ins_type) == 'private')
    ))
)

result = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((LOWER(gender) == 'female') & (LOWER(ins_type) == 'private')))
)

top_drug_by_adverse_events = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatments_used_in.start_dt)) &
            (MONTH(reported_dt) == MONTH(treatments_used_in.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

result = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(LOWER(drug.drug_type) == LOWER("Biologic"))) == 1
).PARTITION(name="states", by=(loc_state,)).CALCULATE(
    state=loc_state
)

distinct_doctor_states = DermTreatment.Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(LOWER(drug.drug_type) == 'biologic')) == 1
).PARTITION(
    name="states", by=loc_state
).CALCULATE(
    state=loc_state
)

result = Drugs.WHERE(
    HASNOT(treatments_used_in) == 1
).CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name
)

top_diagnoses = DermTreatment.Diagnoses.WHERE(
    HAS(treatments_for.outcome_records) == 1
).CALCULATE(
    diagnosis_name=diag_name,
    max_itch_score=MAX(treatments_for.outcome_records.day100_itch_vas),
    num_patients=NDISTINCT(treatments_for.patient.patient_id)
).TOP_K(
    3,
    by=max_itch_score.DESC()
)

top_3_specialties_by_drug_amount = DermTreatment.Treatments.WHERE(
    start_dt >= DATETIME('now', '-6 months')
).CALCULATE(
    doc_specialty=doctor.speciality
).PARTITION(
    name="specialty_groups", by=doc_specialty
).CALCULATE(
    specialty=doc_specialty,
    number_of_treatments=COUNT(Treatments),
    total_drug_amount=SUM(Treatments.tot_drug_amt)
).TOP_K(3, by=total_drug_amount.DESC())

result = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            CONTAINS(LOWER(diagnosis.diag_name), 'psoriasis') &
            (drug.fda_appr_dt != None) &
            (DATEDIFF("days", end_dt, DATETIME('now')) <= 180)
        )
    )
)

result = Treatments.WHERE(
    HAS(adverse_events) == 1
).adverse_events.WHERE(
    DATEDIFF("days", treatment.start_dt, reported_dt) <= 10
).CALCULATE(
    treatment_id=treatment.treatment_id,
    treatment_start_date=treatment.start_dt,
    adverse_event_date=reported_dt,
    adverse_event_description=description
)

result = Treatments.WHERE(
    is_placebo == True
).WHERE(
    HAS(concomitant_meds.WHERE(
        DATEDIFF("days", start_dt, concomitant_meds.start_dt) <= 14
    )) == 1
).concomitant_meds.CALCULATE(
    treatment_id=treatment.treatment_id,
    treatment_start_dt=treatment.start_dt,
    treatment_end_dt=treatment.end_dt,
    concomitant_med_start_dt=start_dt,
    concomitant_med_end_dt=end_dt
)

result = Patients.WHERE(
    (LOWER(gender) == 'male') & 
    (LOWER(ins_type) == 'private')
).CALCULATE(
    age_in_years = DATEDIFF("years", date_of_birth, DATETIME('now'))
).CALCULATE(
    average_age = AVG(age_in_years)
)

avg_age_of_patients = DermTreatment.CALCULATE(
    avg_patient_age=AVG(
        Patients.WHERE(
            (LOWER(gender) == 'male') & (LOWER(ins_type) == 'private')
        ).CALCULATE(
            age_in_years=DATEDIFF("years", date_of_birth, 'now')
        ).age_in_years
    )
)

result = Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
    DATEDIFF("days", created_at, DATETIME('now')) <= 7
).CALCULATE(
    num_transactions=COUNT(Transactions),
    total_amount=SUM(amount)
).SINGULAR()

result = Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

result = Users.WHERE(
    LOWER(user_type) != LOWER('merchant')
).CALCULATE(
    user_id=uid,
    total_transactions_sent=COUNT(transactions_sent)
)

result = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & 
            (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_seconds
    )
).WHERE(
    HAS(sessions.WHERE(
        (session_start_ts >= "2023-06-01") & 
        (session_start_ts < "2023-06-08")
    )) == 1
).ORDER_BY(total_duration.DESC())

user_session_duration = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
        ).CALCULATE(
            duration_in_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_in_seconds
    )
).ORDER_BY(total_duration.DESC())

result = Ewallet.CALCULATE(
    total_count=COUNT(UserSessions.WHERE(
        DATEDIFF("days", session_start_ts, DATETIME('now')) <= 30
    ))
)

result = Ewallet.CALCULATE(
    str_value = COUNT(
        Transactions.WHERE(
            (created_at >= DATETIME('now', 'start of month', '-1 month')) &
            (created_at < DATETIME('now', 'start of month')) &
            (LOWER(status) == 'success')
        )
    ) / COUNT(
        Transactions.WHERE(
            (created_at >= DATETIME('now', 'start of month', '-1 month')) &
            (created_at < DATETIME('now', 'start of month'))
        )
    )
)

previous_month_transactions = Transactions.WHERE(
    (created_at >= DATETIME('now', 'start of month', '-1 month')) & 
    (created_at < DATETIME('now', 'start of month'))
)
str_calculation = Ewallet.CALCULATE(
    successful_transactions=COUNT(previous_month_transactions.WHERE(LOWER(status) == 'success')),
    total_transactions=COUNT(previous_month_transactions)
).CALCULATE(
    str=IFF(total_transactions > 0, successful_transactions / total_transactions, 0.0)
)

result = Transactions.WHERE(receiver_type == 1).CALCULATE(
    merchant_id=receiver_id
).PARTITION(name="merchants", by=merchant_id).CALCULATE(
    merchant_id=merchant_id
)

distinct_merchant_ids = Ewallet.Transactions.WHERE(receiver_type == 1).PARTITION(name="merchants", by=(receiver_id)).CALCULATE(
    merchant_id=receiver_id
)

result = Users.WHERE(
    HAS(notifications.WHERE(CONTAINS(LOWER(notification_type), "transaction"))) == 1
).CALCULATE(
    user_id=uid
)

distinct_transaction_notification_users = Notifications.WHERE(
    LOWER(notification_type) == 'transaction'
).PARTITION(
    name='distinct_users', by=user_id
).CALCULATE(
    user_id
)

result = Merchants.WHERE(
    HAS(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions=COUNT(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )),
    total_amount=SUM(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    ).amount)
).TOP_K(2, by=total_amount.DESC())

active_retail_merchants_balances_today = Ewallet.Merchants.WHERE(
    (LOWER(status) == 'active') & CONTAINS(LOWER(category), 'retail')
).balances.WHERE(
    updated_at >= DATETIME('now', 'start of day')
)

median_balance_result = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(active_retail_merchants_balances_today.balance)
)

earliest_snapshots_in_2023 = Ewallet.UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023)
earliest_date_in_2023 = Ewallet.CALCULATE(
    min_date=MIN(earliest_snapshots_in_2023.snapshot_date)
)
result = earliest_date_in_2023.CALCULATE(
    avg_tx_limit_daily=AVG(
        earliest_snapshots_in_2023.WHERE(snapshot_date == min_date).tx_limit_daily
    ),
    avg_tx_limit_monthly=AVG(
        earliest_snapshots_in_2023.WHERE(snapshot_date == min_date).tx_limit_monthly
    ),
)

average_session_duration_by_device = UserSessions.PARTITION(
    name="sessions_by_device", by=(device_type)
).CALCULATE(
    device_type=device_type,
    average_duration_seconds=AVG(
        UserSessions.CALCULATE(
            duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration
    )
)

result = Users.WHERE(
    HASNOT(
        notifications.WHERE(
            (created_at >= user.created_at) & 
            (created_at <= DATETIME(user.created_at, '+1 year'))
        )
    ) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)

users_without_first_year_notifications = Users.WHERE(
    HASNOT(
        notifications.WHERE(
            (created_at >= Users.created_at) & (created_at < DATETIME(Users.created_at, '+1 year'))
        )
    ) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
